// ============================================================================
//  Print-in-place flapping butterfly  -  fully parametric OpenSCAD model
//  ---------------------------------------------------------------------------
//  Three rigid bodies, printed assembled in one job:
//    * torso (fixed)
//    * left wing  (revolute joint about +Z at (0, +pivot_y))
//    * right wing (revolute joint about +Z at (0, -pivot_y))
//
//  Datum / delivery pose: wings at their neutral (0 deg) position.
//  X = body longitudinal axis (head towards +X)
//  Y = left/right wing span (+Y = left wing)
//  Z = vertical / build direction
//
//  Print: flat on the bed, Z up, no supports.  All three bodies start on Z=0.
//  No fasteners, no inserted pins, no post-print assembly.
// ============================================================================

// ----------------------------- selectable part -----------------------------
// "all" | "torso" | "left_wing" | "right_wing"
PART = "all";

// ------------------------------- print setup --------------------------------
LAYER_H       = 0.2;    // mm, specified FDM layer height
NOZZLE_D       = 0.4;   // mm, specified nozzle
$fn           = 96;     // smooth circular features

// ------------------------------ joint clearances ---------------------------
RADIAL_CLEAR  = 0.50;   // mm, per side, pin/hole (spec: 0.40..0.60)
AXIAL_TOP     = 0.60;   // mm, wing top to torso retaining bridge
AXIAL_BOT     = 0.55;   // mm, wing shoulder to lower retaining flange
// (both are non-zero and are printed as air, never as support material)

// ------------------------------ torso envelope -----------------------------
BODY_Z        = 3.20;   // mm, main torso thickness
THORAX_Z      = 5.00;   // mm, top of raised thorax / retaining bridge
BODY_HALF_W   = 5.80;   // mm, thorax half width at the wing root
HEAD_X        = 24.0;   // mm, head centre
HEAD_R        = 5.20;   // mm, head radius
ABDOMEN_X     = -23.0;  // mm, abdomen centre
ABDOMEN_RX    = 15.50;  // mm
ABDOMEN_RY    = 5.20;   // mm

// ------------------------------- wing / joint ------------------------------
PIVOT_Y       = 13.50;  // mm, |Y| of each wing pivot
PIN_R         = 2.50;   // mm, fixed pin radius
WING_HOLE_R   = PIN_R + RADIAL_CLEAR;          // 3.00 mm
FLANGE_R      = 4.20;   // mm, lower axial-retaining flange
CBORE_R       = FLANGE_R + RADIAL_CLEAR;       // 4.70 mm
FLANGE_H      = 0.80;   // mm, lower flange thickness
CBORE_H       = 0.85;   // mm, plain counterbore before 45 deg shoulder
WING_T        = 3.20;   // mm, wing plate thickness
HUB_R         = 6.20;   // mm, round rotating root hub
SHOULDER_H    = WING_T - CBORE_H;              // 2.35 mm
SHOULDER_RISE = CBORE_R - WING_HOLE_R;         // 1.70 mm (45 deg)
BRIDGE_Z0     = WING_T + AXIAL_TOP;            // 3.80 mm
BRIDGE_R      = 5.00;   // mm, retaining bridge cap radius (> WING_HOLE_R)

// Wing outline in local (v,u) coordinates:
//   v = local X, u = distance outward from the pivot in +Y (left wing).
// The outline is deliberately kept outboard of the torso; all points that
// can swing inboard stay at least ~5 mm clear of the torso in the full range.
WING_OUTLINE = [
    [  2.5,  4.0], [  8.0,  8.5], [ 16.0, 12.0], [ 24.0, 16.5],
    [ 30.0, 22.0], [ 31.0, 27.5], [ 28.0, 32.2], [ 22.0, 35.2],
    [ 14.0, 35.8], [  7.0, 34.0], [  3.0, 29.0], [ -4.0, 33.0],
    [-12.0, 33.5], [-20.0, 30.0], [-27.0, 24.0], [-29.0, 18.0],
    [-26.0, 12.0], [-19.0,  8.0], [ -9.0,  6.0], [ -2.5,  4.0]
];

// ------------------------------- small helpers -----------------------------
module ellipse2d(cx, cy, rx, ry) {
    translate([cx, cy]) scale([rx, ry]) circle(r = 1);
}

module wing_vein_grooves_2d() {
    // Recessed top-surface decoration only.  All veins start at u >= 10 mm,
    // i.e. well outside the radius swept by the retaining bridge (5 mm) and
    // well away from the pin, so they cannot affect joint motion.
    vein = 0.55;                         // groove width
    segs = [
        [[  2.0, 10.5], [ 12.0, 18.0]], [[ 12.0, 18.0], [ 25.0, 27.0]],
        [[  0.0, 11.0], [  8.0, 21.0]], [[  8.0, 21.0], [ 19.0, 32.0]],
        [[ -2.5, 11.0], [  1.0, 22.0]], [[  1.0, 22.0], [  7.0, 32.0]],
        [[ -5.0, 10.5], [ -7.0, 21.0]], [[ -7.0, 21.0], [-10.0, 30.0]],
        [[ -6.5, 10.0], [-15.0, 17.0]], [[-15.0, 17.0], [-25.0, 22.5]],
        // a couple of cross veins
        [[  4.0, 24.0], [ 12.0, 26.0]], [[ 12.0, 26.0], [ 20.0, 29.0]],
        [[ -8.0, 24.0], [ -4.0, 26.0]], [[ -4.0, 26.0], [  2.0, 27.5]]
    ];
    for (s = segs) {
        hull() {
            translate(s[0]) circle(d = vein);
            translate(s[1]) circle(d = vein);
        }
    }
    // shallow decorative wing spots
    for (p = [[13.5, 27.0, 1.05], [20.5, 30.0, 0.90], [-14.5, 24.0, 0.95]]) {
        translate([p[0], p[1]]) circle(r = p[2]);
    }
}

module wing_outline_2d() {
    polygon(points = WING_OUTLINE);
}

// ============================================================================
//  TORSO
// ============================================================================
module torso_footprint_2d() {
    union() {
        ellipse2d(ABDOMEN_X, 0, ABDOMEN_RX, ABDOMEN_RY);   // abdomen
        ellipse2d( -9.0, 0, 8.00, 4.80);                  // waist
        ellipse2d(  0.0, 0, 10.0, BODY_HALF_W);           // thorax
        ellipse2d(  9.0, 0, 5.20, 4.20);                  // neck
        ellipse2d(HEAD_X, 0, HEAD_R, HEAD_R);              // head

        // antennae - flat, bed-supported, kept inside |Y| < 6.8 mm
        for (s = [-1, 1]) {
            hull() {
                translate([27.5, s * 2.20]) circle(d = 0.90);
                translate([33.5, s * 5.20]) circle(d = 0.70);
            }
            hull() {
                translate([33.5, s * 5.20]) circle(d = 0.70);
                translate([39.8, s * 4.40]) circle(d = 0.80);
            }
            translate([39.8, s * 4.40]) circle(d = 2.60);  // antenna club
        }
    }
}

module torso() {
    difference() {
        union() {
            // main flat torso (abdomen, thorax, head, antennae)
            linear_extrude(height = BODY_Z) torso_footprint_2d();

            // raised, stepped thorax: lower step and upper bridge support
            translate([0, 0, BODY_Z])
                linear_extrude(height = 0.60) ellipse2d(0, 0, 9.80, 5.45);
            translate([0, 0, BODY_Z + 0.60])
                linear_extrude(height = THORAX_Z - (BODY_Z + 0.60))
                    ellipse2d(0, 0, 8.80, 4.80);

            // raised compound eyes
            for (s = [-1, 1])
                translate([HEAD_X + 2.0, s * 3.0, BODY_Z - 0.30])
                    cylinder(h = 0.55, r = 1.15);

            // two complete pin / flange / retaining-bridge joints
            for (s = [-1, 1]) {
                // lower axial retaining flange (sits on the build plate)
                translate([0, s * PIVOT_Y, 0])
                    cylinder(h = FLANGE_H, r = FLANGE_R);
                // fixed pin, from build plate to the top of the bridge
                translate([0, s * PIVOT_Y, 0])
                    cylinder(h = THORAX_Z, r = PIN_R);
                // upper retaining bridge and cap; also a torsional support
                // between the raised thorax and the pin.  Its underside is
                // AXIAL_TOP above the wing, so it never needs support.
                translate([0, 0, BRIDGE_Z0])
                    linear_extrude(height = THORAX_Z - BRIDGE_Z0)
                        hull() {
                            translate([0, s * 4.10]) circle(r = 3.00);
                            translate([0, s * PIVOT_Y]) circle(r = BRIDGE_R);
                        }
            }
        }

        // abdomen segmentation grooves (0.30 mm deep, decoration only)
        for (x = [-31.0, -26.0, -21.0, -16.0])
            translate([x, 0, BODY_Z - 0.30])
                cube([0.65, 13.0, 0.32], center = true);

        // eye pupils / shallow eye recess
        for (s = [-1, 1])
            translate([HEAD_X + 2.0, s * 3.0, BODY_Z + 0.02])
                cylinder(h = 0.34, r = 0.62);
    }
}

